import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';

describe('ToolRegistry unit tests', () => {
  beforeAll(() => {
    setLogger({
      debug: () => {},
      info: () => {},
      warn: () => {},
      error: () => {},
    });
  });

  afterAll(() => {
    setLogger(undefined);
  });

  it('validates input against schema and rejects missing required fields', async () => {
    const registry = new ToolRegistry();
    let calls = 0;
    registry.register(
      {
        name: 'test_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        calls++;
        return 'ok';
      }
    );

    const response = await registry.execute('test_tool', {});

    expect(calls).toBe(0);
    expect(response.result).toContain('location');
    expect(response.result).toContain('required');
  });

  it('throws at register time naming the tool when a static inputSchema cannot be compiled', () => {
    const registry = new ToolRegistry();
    expect(() =>
      registry.register(
        {
          name: 'broken_tool',
          description: 'test',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'invalid-type' as any}},
          },
        },
        async () => 'ok'
      )
    ).toThrow(/broken_tool/);
  });

  it('caches compiled validators by schema object reference', async () => {
    const registry = new ToolRegistry();
    const schema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };

    registry.register(
      () => ({
        name: 'cached_tool',
        description: 'test',
        inputSchema: schema,
      }),
      async () => 'ok'
    );

    await registry.execute('cached_tool', {location: 'Paris'});
    const response = await registry.execute('cached_tool', {location: 'London'});
    expect(response.result).toBe('ok');
  });
});

import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';

describe('ToolRegistry unit tests', () => {
  beforeAll(() => {
    setLogger({
      debug: () => {},
      info: () => {},
      warn: () => {},
      error: () => {},
    });
  });

  afterAll(() => {
    setLogger(undefined);
  });

  it('validates input against schema and rejects missing required fields', async () => {
    const registry = new ToolRegistry();
    let calls = 0;
    registry.register(
      {
        name: 'test_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        calls++;
        return 'ok';
      }
    );

    const response = await registry.execute('test_tool', {});

    expect(calls).toBe(0);
    expect(response.result).toContain('location');
    expect(response.result).toContain('required');
  });

  it('throws at register time naming the tool when a static inputSchema cannot be compiled', () => {
    const registry = new ToolRegistry();
    expect(() =>
      registry.register(
        {
          name: 'broken_tool',
          description: 'test',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'invalid-type' as any}},
          },
        },
        async () => 'ok'
      )
    ).toThrow(/broken_tool/);
  });

  it('caches compiled validators by schema object reference', async () => {
    const registry = new ToolRegistry();
    const schema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };

    registry.register(
      () => ({
        name: 'cached_tool',
        description: 'test',
        inputSchema: schema,
      }),
      async () => 'ok'
    );

    await registry.execute('cached_tool', {location: 'Paris'});
    const response = await registry.execute('cached_tool', {location: 'London'});
    expect(response.result).toBe('ok');
  });

  it('asserts valid input with an unlisted extra property is passed through to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    let receivedInput: any;
    registry.register(
      {
        name: 'extra_props',
        description: 'test',
        inputSchema: {type: 'object', properties: {a: {type: 'string'}}},
      },
      async (input) => {
        receivedInput = input;
        return 'ok';
      }
    );

    await registry.execute('extra_props', {a: 'val', b: 'extra'});
    expect(receivedInput).toEqual({a: 'val', b: 'extra'});
  });

  it('rejects a wrong-typed field naming the field and expected type without leaking the offending value', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'type_check',
        description: 'test',
        inputSchema: {type: 'object', properties: {age: {type: 'number'}}},
      },
      async () => 'ok'
    );

    const response = await registry.execute('type_check', {age: 'not-a-number'});
    expect(response.result).toContain('age');
    expect(response.result).toContain('number');
    expect(response.result).not.toContain('not-a-number');
  });
});

